    except Exception:
        return error_response(422, "invalid_grant_request")
    if not isinstance(payload, dict) or set(payload) != {"items"}:
        return error_response(422, "invalid_grant_request")

    raw_items = payload["items"]
    if not isinstance(raw_items, list) or not raw_items:
        return error_response(422, "invalid_grant_request")

